import Foundation
import zlib

/// Viewer assets are the same pinned CSS/runtime/marked/highlight sources as the web exporter.
/// They are gzip-packed in the binary, then expanded only while producing a standalone HTML file.
enum ConversationExportAssets {
    static let skin = decode(skinGZIP)
    static let runtime = [
        decode(runtimeAnalyticsGZIP),
        decode(runtimeRenderGZIP),
        decode(runtimeMessagesGZIP),
        decode(runtimeUIGZIP),
    ].joined(separator: "\n")
    static let marked = decode(markedGZIP)
    static let highlight = decode(highlightGZIP)
    static let highlightCSS = decode(highlightCSSGZIP)

    private static let skinGZIP = ""
    private static let runtimeAnalyticsGZIP = ""
    private static let runtimeRenderGZIP = ""
    private static let runtimeMessagesGZIP = ""
    private static let runtimeUIGZIP = ""
    private static let markedGZIP = ""
    private static let highlightGZIP = ""
    private static let highlightCSSGZIP = ""

    private static func decode(_ encoded: String) -> String {
        guard let compressed = Data(base64Encoded: encoded), compressed.count >= 4 else { return "" }
        let sizeOffset = compressed.count - 4
        let expected = Int(compressed.u32LE(at: sizeOffset))
        guard expected >= 0, expected <= 4 * 1_024 * 1_024 else { return "" }
        var output = Data(count: max(expected, 1))
        var stream = z_stream()
        guard inflateInit2_(
            &stream,
            MAX_WBITS + 16,
            ZLIB_VERSION,
            Int32(MemoryLayout<z_stream>.size)
        ) == Z_OK else { return "" }
        defer { inflateEnd(&stream) }
        let outputCapacity = output.count
        let status: Int32 = compressed.withUnsafeBytes { input in
            output.withUnsafeMutableBytes { destination in
                stream.next_in = UnsafeMutablePointer<Bytef>(
                    mutating: input.bindMemory(to: Bytef.self).baseAddress
                )
                stream.avail_in = uInt(compressed.count)
                stream.next_out = destination.bindMemory(to: Bytef.self).baseAddress
                stream.avail_out = uInt(outputCapacity)
                return inflate(&stream, Z_FINISH)
            }
        }
        guard status == Z_STREAM_END, Int(stream.total_out) == expected else { return "" }
        output.count = expected
        return String(data: output, encoding: .utf8) ?? ""
    }
}

private extension Data {
    func u32LE(at offset: Int) -> UInt32 {
        UInt32(self[index(startIndex, offsetBy: offset)])
            | UInt32(self[index(startIndex, offsetBy: offset + 1)]) << 8
            | UInt32(self[index(startIndex, offsetBy: offset + 2)]) << 16
            | UInt32(self[index(startIndex, offsetBy: offset + 3)]) << 24
    }
}
